html:
{% for page in layout %}
<div class="page-break angebot-wrapper">
	<style>
		.print-format {
			margin-top: 14mm;
		}
		.angebot-wrapper {
			font-family: "Inter", Arial, sans-serif;
			color: #1a1a1a;
			font-size: 12px;
		}
		.print-format-body {
			padding: 6px 4px !important;
		}
		body {
			margin-bottom: 0mm !important;
			padding: 0px !important;
		}
		.doc-title {
			font-size: 26px;
			font-weight: 700;
			margin: 0;
			color: #1a1a1a;
		}
		.doc-number {
			font-size: 13px;
			color: #5b6b8c;
			margin: 2px 0 10px 0;
		}
		.text-muted {
			color: #7c7c7c;
		}
		.text-right {
			text-align: right;
		}
		.text-center {
			text-align: center;
		}
		.text-bold {
			font-weight: bold;
		}
		p.intro {
			margin: 4px 0 14px 0;
		}
		table.items-table {
			width: 100%;
			table-layout: fixed;
			border-collapse: collapse;
		}
		table.items-table-head {
			margin-bottom: 0;
		}
		table.items-table-body {
			margin-top: -1px;
		}
		table.items-table-last {
			margin-bottom: 10px;
		}
		table.items-table th,
		table.items-table td {
			border: 1px solid #cfcfcf;
			padding: 4px 6px;
			font-size: 10.5px;
			vertical-align: top;
			word-wrap: break-word;
			overflow-wrap: break-word;
		}
		table.items-table thead th {
			background: #f5f5f5;
			font-weight: bold;
			text-align: left;
			white-space: nowrap;
			font-size: 9.5px;
			padding: 4px 4px;
		}
		tbody.item-group {
			page-break-inside: avoid;
			break-inside: avoid;
		}
		tr.main-row td {
			border-bottom: 0;
		}
		tr.main-row.main-last td {
			border-bottom: 1px solid #cfcfcf;
		}
		tr.sub-row td {
			border-top: 0;
			border-bottom: 0;
			font-size: 10px;
			font-style: italic;
			color: #8c8c8c;
			padding-top: 2px;
			padding-bottom: 2px;
		}
		tr.sub-row.sub-last td {
			border-bottom: 1px solid #cfcfcf;
		}
		.sub-label {
			padding-left: 18px !important;
		}
		.sub-value {
			font-weight: 400;
		}
		.sub-text {
			color: #8c8c8c;
		}
		.col-pos { width: 6%; white-space: nowrap; }
		.col-teilenummer { width: 14%; }
		.col-name { width: 22%; }
		.col-desc { width: 24%; }
		.col-qty { width: 9%; white-space: nowrap; }
		.col-rate { width: 10%; white-space: nowrap; }
		.col-amount { width: 15%; white-space: nowrap; }

		table.bottom-table {
			width: 100%;
			margin-top: 20px;
			page-break-inside: avoid;
			break-inside: avoid;
		}
		table.bottom-table > tbody > tr > td {
			vertical-align: top;
		}
		.terms-cell {
			width: 60%;
			padding-right: 20px;
		}
		table.totals-table {
			width: 100%;
		}
		table.totals-table td {
			padding: 4px 0;
			border-bottom: 1px solid #e5e5e5;
		}
		table.totals-table tr.grand-total td {
			border-bottom: none;
			border-top: 1px solid #1a1a1a;
			font-weight: bold;
			padding-top: 8px;
		}

	</style>

	{% if loop.index == 1 %}
	{{ letter_head | safe }}
	<div style="width: 100%; margin: 0 0 48px 0; overflow: hidden;">
		<div style="float: right; width: 40%; text-align: right;">
			<h1 class="doc-title">{{ _("Angebot") }}</h1>
			<div class="doc-number">{{ doc.name }}</div>
			<div style="margin-top: 8px;">
				<span class="text-muted">{{ _("Datum") }}:</span> {{ frappe.utils.format_date(doc.transaction_date) }}
			</div>
		</div>
		<div style="overflow: hidden;">
			{% set delivery_address_name = doc.shipping_address_name or doc.customer_address %}
			{% if delivery_address_name %}
				{% set customer_address = frappe.db.get_value("Address", delivery_address_name, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
				<b>{{ doc.customer_name }}</b><br>
				{{ customer_address.address_line1 or "" }}<br>
				{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}
				{{ customer_address.pincode or "" }} {{ customer_address.city or "" }}<br>
				{{ customer_address.country or "" }}
			{% else %}
				<b>{{ doc.customer_name }}</b>
			{% endif %}
		</div>
	</div>

	{% set contact = frappe.get_doc("Contact", doc.contact_person) if doc.contact_person else None %}
	{% set anrede = None %}
	{% if contact %}
		{% if contact.salutation == "Mr" %}{% set anrede = "Herr" %}
		{% elif contact.salutation in ("Mrs", "Ms", "Madam", "Miss") %}{% set anrede = "Frau" %}
		{% endif %}
	{% endif %}
	<p class="intro">
		{% if anrede and contact.last_name %}
			Sehr geehrte{{ "r" if anrede == "Herr" else "" }} {{ anrede }} {{ contact.last_name }},
		{% else %}
			Sehr geehrte Damen und Herren,
		{% endif %}
		<br><br>
		wir bedanken uns für Ihre Anfrage und unterbreiten Ihnen folgendes Angebot:
	</p>

	<!-- Items Table -->
	{% macro de_money(v) -%}
		{{ "{:,.2f}".format((v or 0) | float) | replace(",", "X") | replace(".", ",") | replace("X", ".") }}
	{%- endmacro %}
	{% set sonderkosten_labels = {
		"ART-Rüstkosten-Hohenstein GmbH": "Rüstkosten",
		"ART-Messkosten-Hohenstein GmbH": "Messkosten",
		"ART-Einmalkosten-Hohenstein GmbH": "Einmalkosten",
		"ART-Expresskosten-Hohenstein GmbH": "Expresskosten"
	} %}
	{% set main_items = doc.items | selectattr("item_group", "ne", "Sonderkosten") | list %}
	<table class="items-table items-table-head">
		<thead>
			<tr>
				<th class="col-pos text-center">{{ _("Pos") }}</th>
				<th class="col-teilenummer">{{ _("Teilenummer") }}</th>
				<th class="col-name">{{ _("Artikelbezeichnung") }}</th>
				<th class="col-desc">{{ _("Beschreibung") }}</th>
				<th class="col-qty text-right">{{ _("Menge") }}</th>
				<th class="col-rate text-right">{{ _("Preis") }}</th>
				<th class="col-amount text-right">{{ _("Betrag") }}</th>
			</tr>
		</thead>
	</table>
	{% for main in main_items %}
	{% set teilenummer = frappe.db.get_value("Item", main.item_code, "custom_teilenummer") %}
	{% set sub_rows = (doc.items | selectattr("item_group", "eq", "Sonderkosten") | selectattr("custom_parent_item_id", "eq", main.custom_parent_item_id) | list) if main.custom_parent_item_id else [] %}
	<div class="item-group" style="page-break-inside: avoid; break-inside: avoid;{% if not loop.first %} margin-top: 3px;{% endif %}">
		<table class="items-table items-table-body {% if loop.last %}items-table-last{% endif %}">
			<tbody>
				<tr class="main-row {% if not sub_rows %}main-last{% endif %}">
					<td class="col-pos pos text-center">{{ loop.index }}</td>
					<td class="col-teilenummer">{{ teilenummer or main.item_code }}</td>
					<td class="col-name">{{ main.item_name }}</td>
					<td class="col-desc desc">{{ frappe.utils.strip_html(main.description) if main.description else "" }}</td>
					<td class="col-qty text-right">{{ main.get_formatted("qty", 0) }}</td>
					<td class="col-rate text-right">{{ de_money(main.net_rate) }} €</td>
					<td class="col-amount text-right">{{ de_money(main.net_amount) }} €</td>
				</tr>
				{% for sub in sub_rows %}
				{% set label = sonderkosten_labels.get(sub.item_code, sub.item_name) %}
				{% set extra_text = frappe.utils.strip_html(sub.description) if sub.description and sub.description != sub.item_name else "" %}
				<tr class="sub-row {% if loop.last %}sub-last{% endif %}">
					<td class="col-pos"></td>
					<td colspan="3" class="sub-label">↳ {{ teilenummer or main.item_code }} {{ label }}{% if extra_text %} <span class="sub-text">„{{ extra_text }}"</span>{% endif %}</td>
					<td class="col-qty text-right"></td>
					<td class="col-rate text-right"></td>
					<td class="col-amount text-right sub-value">+ {{ de_money(sub.net_amount) }} €</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>
	</div>
	{% endfor %}
	{% endif %}

	{% if loop.index == layout|len %}
	<table class="bottom-table">
		<tr>
			<td class="terms-cell">
				{% if doc.terms %}
					{{ doc.terms }}
				{% endif %}
				<br>
				Über eine Auftragserteilung würden wir uns freuen und verbleiben<br><br>
				Mit freundlichen Grüßen<br>
				{{ frappe.db.get_value("User", doc.owner, "full_name") or "" }}
			</td>
			<td style="width: 40%">
				<table class="totals-table">
					<tr>
						<td class="text-muted">{{ _("Netto Summe") }}</td>
						<td class="text-right">{{ "{:,.2f}".format(doc.net_total)|replace(",", "X")|replace(".", ",")|replace("X", ".") }} EUR</td>
					</tr>
					{%- for tax in doc.taxes -%}
						{%- if tax.tax_amount -%}
						<tr>
							<td class="text-muted">{{ tax.description }}</td>
							<td class="text-right">{{ "{:,.2f}".format(tax.tax_amount)|replace(",", "X")|replace(".", ",")|replace("X", ".") }} EUR</td>
						</tr>
						{%- endif -%}
					{%- endfor -%}
					<tr class="grand-total">
						<td>{{ _("Gesamtbetrag") }}</td>
						<td class="text-right">{{ "{:,.2f}".format(doc.grand_total)|replace(",", "X")|replace(".", ",")|replace("X", ".") }} EUR</td>
					</tr>
				</table>
			</td>
		</tr>
	</table>
	{% endif %}

	<div {% if print_settings.repeat_header_footer %} id="header-html" class="visible-pdf" {% endif %}>
		<style>
			/* wkhtmltopdf rendert --header-html als eigenstaendiges Dokument -
			   das <style> der Hauptseite wird NICHT mit uebernommen, daher hier dupliziert. */
			#header-html {
				font-family: "Inter", Arial, sans-serif;
			}
			.items-header-spacer {
				height: 10mm;
				line-height: 10mm;
				font-size: 1px;
			}
			table.items-table-repeat {
				width: 100%;
				table-layout: fixed;
				border-collapse: collapse;
			}
			table.items-table-repeat th {
				background: #f5f5f5;
				font-weight: bold;
				text-align: left;
				white-space: nowrap;
				font-size: 9.5px;
				padding: 4px 4px;
				border: 1px solid #cfcfcf;
			}
			.col-pos { width: 6%; }
			.col-teilenummer { width: 14%; }
			.col-name { width: 22%; }
			.col-desc { width: 24%; }
			.col-qty { width: 9%; }
			.col-rate { width: 10%; }
			.col-amount { width: 15%; }
		</style>
		<div id="items-header-repeat">
			<div class="items-header-spacer">&nbsp;</div>
			<table class="items-table-repeat">
				<tr>
					<th class="col-pos text-center">{{ _("Pos") }}</th>
					<th class="col-teilenummer">{{ _("Teilenummer") }}</th>
					<th class="col-name">{{ _("Artikelbezeichnung") }}</th>
					<th class="col-desc">{{ _("Beschreibung") }}</th>
					<th class="col-qty text-right">{{ _("Menge") }}</th>
					<th class="col-rate text-right">{{ _("Preis") }}</th>
					<th class="col-amount text-right">{{ _("Betrag") }}</th>
				</tr>
			</table>
		</div>
		<script>
			/* Auf Seite 1 haben wir schon einen eigenen Tabellenkopf direkt ueber der
			   ersten Position - hier nur ab Seite 2 zeigen, sonst doppelt/verschoben.
			   wkhtmltopdf uebergibt den aktuellen Seiten-Index als "page" im Query-String. */
			window.onload = function () {
				var vars = {};
				var parts = window.location.search.substring(1).split("&");
				for (var i = 0; i < parts.length; i++) {
					var pair = parts[i].split("=");
					vars[pair[0]] = decodeURIComponent(pair[1] || "");
				}
				if (vars.page === "1") {
					var el = document.getElementById("items-header-repeat");
					if (el) { el.style.display = "none"; }
				}
			};
		</script>
	</div>

	<div {% if print_settings.repeat_header_footer %} id="footer-html" class="visible-pdf" {% endif %}>
		{{ footer | safe }}
	</div>
</div>
{% endfor %}
